import multiprocessing as mp, os, sys, time
sys.path.insert(0,"/var/tmp/cap4/ca/task014")
from carbon_market import history
from carbon_market import recover_all as ra
K="k"; d="/var/tmp/cap4/ca/task014/.st"; os.makedirs(d,exist_ok=True)
cp=os.path.join(d,"c.json"); hp=cp+".history"
for p in (hp,hp+".lock",cp,cp+".lock"):
    if os.path.exists(p): os.unlink(p)
N=150
def w(cp,r):
    r.wait()
    for i in range(1,N+1):
        ra._ensure_snapshot(cp,{"version":1,"key":K,"owner":"o","until":i,"items":{"j":[None,None]}})
def rd(hp,q,r):
    r.wait(); dl=time.time()+60; last=0
    while True:
        try: pg=history.get(hp,K,count=1000); v=history.verify(hp,K)
        except FileNotFoundError:
            if time.time()>dl: q.put(("to",)); return
            continue
        s=pg["snapshots"]; n=len(s)
        if [x[0] for x in s]!=list(range(n)) or [x[2]["until"] for x in s]!=list(range(1,n+1)):
            q.put(("bad",)); return
        if v["statuses"]!=["pending"]*v["count"] or v["count"]<last: q.put(("bad2",v,n)); return
        last=v["count"]
        if n>=N and v["count"]>=N: break
        if time.time()>dl: q.put(("to",)); return
    q.put(("ok",))
if __name__=="__main__":
    mp.set_start_method("fork"); r=mp.Event(); q=mp.Queue()
    ps=[mp.Process(target=w,args=(cp,r))]+[mp.Process(target=rd,args=(hp,q,r)) for _ in range(4)]
    for p in ps:p.start()
    r.set(); res=[q.get() for _ in range(4)]
    for p in ps:p.join(5)
    assert all(x[0]=="ok" for x in res), res
    assert history.verify(hp,K)["count"]==N
    print("POST-EDIT STRESS OK")
EOF
